export default async function checkUptime({ url }, context) {
  let current;
  try {
    current = new URL(url);
    if (!["http:", "https:"].includes(current.protocol) || current.username || current.password)
      throw Error();
  } catch {
    throw Error("Configure a valid HTTP(S) URL without credentials");
  }
  const signal = AbortSignal.timeout(10000);
  for (let hop = 0; hop <= 21; hop++) {
    const response = await context.fetch(current.toString(), { method: "GET", signal });
    const location = response.headers.get("location");
    if (response.status >= 300 && response.status < 400 && location) {
      if (hop === 21) throw Error("Too many redirects");
      let target;
      try {
        target = new URL(location, current);
        if (!["http:", "https:"].includes(target.protocol) || target.username || target.password)
          throw Error();
      } catch {
        throw Error("Invalid redirect target");
      }
      current = target;
      continue;
    }
    return { status: response.status };
  }
  throw Error("Too many redirects");
}

