export default async function uptimeTransition({ status }, context) {
  if (!Number.isInteger(status) || status < 100 || status > 599) throw Error("Invalid HTTP status");
  const old = await context.state.get("site-down");
  if (old !== null && typeof old !== "boolean") throw Error("Invalid saved state");
  const down = status >= 500;
  if (down === (old === true)) return { changed: false, down, text: "No change" };
  const when = new Date().toISOString();
  return {
    changed: true,
    down,
    text: down
      ? "🔴 Il sito è DOWN (status " + status + ") — " + when
      : "🟢 Il sito è tornato SU — " + when,
  };
}

